src = open('infer_annotations.py').read()
old_start = src.index(' # a literal default is the strongest signal, as long as usage does not')
old_end = src.index('def infer_default(ctx: FileCtx, default: ast.AST | None) -> str:')
new = ''' ev = collect_param_evidence(ctx, func, name) default_type = infer_default(ctx, default) if default is not None else "" ev_type = evidence_to_type(ev, ctx) # 1) the default value is the strongest signal - but `x=None` gets its type # from usage, and a str default that is clearly used as a path becomes Path if default_type: if default_type == "str" and ev.score("Path") >= 10: return ctx.request("Path") if default_type == "bool": if ev.score("str") >= 10 and ev.score("int") >= 10: return ctx.request("Any") return "bool" if default_type in ("str", "int", "float", "bytes") and ev_type == "str" and default_type in ("int", "float"): # numbers that get str()-ed are still numbers pass return ctx.request(default_type) # 2) usage evidence if ev_type: if ev_type == "dict[str, Any]" and CONTAINER_NAMES.get(name) == "list": return "list[Any]" return ctx.request(ev_type) # 3) names typ = name_based_type(ctx, name) if typ: return ctx.request(typ) if name in ("event", "match", "m", "exc", "exception", "err", "error", "obj", "node", "value", "item", "x", "y", "z", "o", "e", "s", "a", "b", "c", "d", "k", "v", "res", "result", "ret", "payload", "record", "info", "kwargs", "scr", "screen"): return "Any" if name.startswith("_"): return "" return "Any" '''
src = src[:old_start] + new + src[old_end:]
# fix the ` =` spacing: insert annotation *after* the default, or normalise spacing
old_seg = ''' typ = types_for_params[pname] eq = next((t for t in seg_tokens[j + 1:] if t.type == tokenize.OP and t.string == "="), None) if eq is not None: insert_text = f": {typ}" edits.append(Edit(name_tok.end[0], name_tok.end[1], insert_text, "param", f"{func.name}({pname}): {typ}")) # make `x: int=1` -> `x: int = 1` if _char_at(ctx, eq.start[0], eq.start[1] - 1) != " ": edits.append(Edit(eq.start[0], eq.start[1], " ", "param", f"{func.name}({pname}) spacing")) else: edits.append(Edit(name_tok.end[0], name_tok.end[1], f": {typ}", "param", f"{func.name}({pname}): {typ}"))'''
new_seg = ''' typ = types_for_params[pname] eq = next((t for t in seg_tokens[j + 1:] if t.type == tokenize.OP and t.string == "="), None) if eq is not None: if _char_at(ctx, eq.start[0], eq.start[1] - 1) == " ": # `x = 1` -> `x: int = 1` edits.append(Edit(name_tok.end[0], name_tok.end[1], f": {typ}", "param", f"{func.name}({pname}): {typ}")) else: # `x=1` -> `x: int = 1` edits.append(Edit(eq.start[0], eq.start[1], f": {typ} ", "param", f"{func.name}({pname}): {typ}")) else: edits.append(Edit(name_tok.end[0], name_tok.end[1], f": {typ}", "param", f"{func.name}({pname}): {typ}"))'''
assert old_seg in src
src = src.replace(old_seg, new_seg)
open('infer_annotations.py','w').write(src)
print('ok')
